// Read-only real WebGL gate before the complete native journey.
'use strict';
const fs=require('node:fs'),path=require('node:path'),crypto=require('node:crypto'),assert=require('node:assert/strict'),{chromium}=require('playwright');
const GAME='kaopu-minigame-workbench/voxel-train-study/game',out='train-r20-budget-stage';fs.mkdirSync(out,{recursive:true});
const sha=b=>crypto.createHash('sha256').update(b).digest('hex'),stats=a=>{a=a.slice().sort((a,b)=>a-b);return{count:a.length,total:a.reduce((n,x)=>n+x,0),median:a[Math.floor(a.length*.5)],p95:a[Math.floor(a.length*.95)],max:a.at(-1)}};
const inject=`\n;window.__budgetInit=async()=>{game.paused=true;needsRender=false;camera.position.set(9,19,70);cameraTarget.set(-17,2.3,1.2);camera.zoom=1;camera.fov=35;camera.updateProjectionMatrix();camera.lookAt(cameraTarget);let n=0;do{world.update({...game.view(),distance:345,elapsed:12},game.route,{cameraTarget:cameraTarget.toArray(),cameraPosition:camera.position.toArray()});if(++n>400)throw Error('Initial render queue did not settle');}while(world.streetDistrict.proof.pending);for(let i=0;i<3;i++){renderer.render(scene,camera);gl.finish();gl.readPixels(0,0,1,1,gl.RGBA,gl.UNSIGNED_BYTE,new Uint8Array(4));}needsRender=false;return{settleUpdates:n,proof:structuredClone(world.streetDistrict.proof)};};window.__budgetStep=async(distance,drain)=>{const before=structuredClone(world.streetDistrict.proof),t=performance.now();world.update({...game.view(),distance,elapsed:12},game.route,{cameraTarget:cameraTarget.toArray(),cameraPosition:camera.position.toArray()});const updateMs=performance.now()-t,proof=structuredClone(world.streetDistrict.proof),r=performance.now();renderer.shadowMap.needsUpdate=true;renderer.render(scene,camera);const submitMs=performance.now()-r;gl.finish();gl.readPixels(0,0,1,1,gl.RGBA,gl.UNSIGNED_BYTE,new Uint8Array(4));needsRender=false;return{distance,drain,updateMs,submitMs,completeMs:performance.now()-t,glError:gl.getError(),drawCalls:renderer.info.render.calls,triangles:renderer.info.render.triangles,memory:{...renderer.info.memory},beforePending:before.pending,proof};};`;
const result={pass:false,commit:process.env.GITHUB_SHA,scope:'Paused comparison fixture, explicit positions350–440m plus every queued tail update at440m; actual Chromium ANGLE SwiftShader. No native-driving or phone hardware claim.',versions:{},errors:[]};
(async()=>{let browser;try{browser=await chromium.launch({headless:true,args:['--no-sandbox','--use-angle=swiftshader','--enable-unsafe-swiftshader']});
for(const version of ['r20-before-budget','r20']){const context=await browser.newContext({viewport:{width:1280,height:720},deviceScaleFactor:1}),page=await context.newPage();page.setDefaultTimeout(180000);page.on('pageerror',e=>result.errors.push(String(e)));const base='http://127.0.0.1:8765/'+GAME+'/'+version+'/';const source=[];await page.route(base+'app.mjs',async route=>{const r=await route.fetch(),body=await r.text(),file=fs.readFileSync(GAME+'/'+version+'/app.mjs');assert.equal(sha(body),sha(file));source.push({path:GAME+'/'+version+'/app.mjs',sha256:sha(body)});await route.fulfill({response:r,body:body+inject});});await page.goto(base,{waitUntil:'domcontentloaded'});await page.waitForFunction(()=>window.__budgetInit&&__trainDriver.ready&&__trainDriver.getState().streetDistrict.status==='active'&&!__trainDriver.getState().streetDistrict.pending);await page.addStyleTag({content:'#journeyHud,#drivePanel,.screen,#notice,#tutorial,#loading{visibility:hidden!important}'});const init=await page.evaluate(()=>__budgetInit()),rows=[];await page.screenshot({path:out+'/'+version+'-345.png'});
for(let distance=350;distance<=440;distance+=5){const row=await page.evaluate(d=>__budgetStep(d,false),distance);rows.push(row);assert.equal(row.glError,0);assert(!row.proof.error);assert.deepEqual(row.proof.coverage.missing,[]);if(version==='r20')assert(row.proof.coverage.required.every(id=>row.proof.renderBatch.renderedParcelIds.includes(id)),'Actual submitted coverage missing');}
for(let drain=0;rows.at(-1).proof.pending;drain++){assert(drain<400,'Render queue failed to settle');const row=await page.evaluate(()=>__budgetStep(440,true));rows.push(row);assert.equal(row.glError,0);assert(!row.proof.error);assert.deepEqual(row.proof.coverage.missing,[]);if(version==='r20')assert(row.proof.coverage.required.every(id=>row.proof.renderBatch.renderedParcelIds.includes(id)),'Actual submitted coverage missing');}
await page.screenshot({path:out+'/'+version+'-440.png'});result.versions[version]={init,source,rows,cpu:stats(rows.map(r=>r.updateMs)),complete:stats(rows.map(r=>r.completeMs)),maximumDrawCalls:Math.max(...rows.map(r=>r.drawCalls)),maximumTriangles:Math.max(...rows.map(r=>r.triangles))};await context.close();fs.writeFileSync(out+'/result.json',JSON.stringify(result));}
const {decode}=require('../../'+GAME+'/r20/tests/png-audit.cjs');result.pixels=[];for(const d of [345,440]){const a=decode(fs.readFileSync(out+'/r20-before-budget-'+d+'.png')),b=decode(fs.readFileSync(out+'/r20-'+d+'.png'));assert.equal(a.w,b.w);assert.equal(a.h,b.h);let sum=0,changed=0;for(let i=0;i<a.w*a.h;i++){let delta=0;for(let c=0;c<3;c++){const v=Math.abs(a.data[i*a.channels+c]-b.data[i*b.channels+c]);sum+=v;delta=Math.max(delta,v);}if(delta>8)changed++;}result.pixels.push({distance:d,meanAbsoluteChannelError:sum/(a.w*a.h*3),fractionOver8:changed/(a.w*a.h)});}const a=result.versions['r20-before-budget'],b=result.versions.r20;result.cost={maximumCpuRatio:b.cpu.max/a.cpu.max,totalCpuRatio:b.cpu.total/a.cpu.total,queuedTailFrames:b.rows.filter(r=>r.drain).length};result.gates={pixels:result.pixels.every(r=>r.fractionOver8<=.005&&r.meanAbsoluteChannelError<=.25),maximumCpu:result.cost.maximumCpuRatio<=1.05,totalCpu:result.cost.totalCpuRatio<=1.35,noErrors:result.errors.length===0};assert(Object.values(result.gates).every(Boolean),'Small segment budget gate failed; do not proceed to full trip');result.pass=true;
}catch(e){result.failure=e.stack;console.error(e);}finally{fs.writeFileSync(out+'/result.json',JSON.stringify(result));if(browser)await browser.close();}if(!result.pass)process.exitCode=1;})();
